DO $$ BEGIN CREATE TEMP TABLE IF NOT EXISTS _p AS SELECT DISTINCT po.* FROM supplier_invoices s CROSS JOIN LATERAL (SELECT public._sinv_po(s) AS po_id) x JOIN purchase_orders po ON po.id = x.po_id WHERE po.job_id IS NULL; RAISE EXCEPTION 'PROBE2 %', (SELECT string_agg(t,'|') FROM (SELECT left(coalesce(description,notes),16) t FROM _p WHERE btrim(coalesce(description,notes,''))<>'' GROUP BY 1 ORDER BY count(*) DESC LIMIT 10) z); END $$;
